<script setup>
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {createPortfolioAdvisor,exposureChart,correlationChart} from './usePortfolioAdvisor.js'
import {dateTime} from './model.js'
import PrototypeChart from './PrototypeChart.vue'
import AdvisorDialogue from './AdvisorDialogue.vue'
import {pendingTaskDraft} from './questionUnderstanding.js'
import ResearchDepth from './ResearchDepth.vue'
const props=defineProps({id:String}),emit=defineEmits(['started'])
const ctl=createPortfolioAdvisor({started:r=>emit('started',r)}),{state,error,busy}=ctl
const blank=()=>({entity:'',cost_price:'',shares:'',sellable_shares:'',bought_today:'0',horizon:'SWING',route_id:'AUTO'})
const assets=ref([blank(),blank()]),cash=ref(''),reserve=ref('0'),declared=ref(false),origin=ref('USER_DECLARED'),original=ref([])
const question=ref('请结合账户总仓位、行业集中度和相关性，给出减仓、加仓和调仓建议。'),refresh=ref(false),formError=ref(''),initialLoading=ref(Boolean(props.id)),parent=ref(null)
const prefs=ref({equity_cap:'80',single_cap:'10',industry_cap:'25',correlation_threshold:'75',correlated_cap:'35',risk_per_trade:'0.5',total_risk:'2',trend_allocation:'40',quality_allocation:'40',liquidity_cap:'0.1',trim_fraction:'50',commission_rate:'0.03',minimum_commission:'5',other_sell_cost_rate:'0.1',other_buy_cost_rate:'0.01'})
const fields=[['equity_cap','总股票仓位上限（%）',100],['single_cap','单股上限（%）',50],['industry_cap','行业上限（%）',100],['correlation_threshold','正相关分组阈值（%）',99.99],['correlated_cap','相关持仓群上限（%）',100],['risk_per_trade','本笔风险预算（%）',5],['total_risk','账户风险预算（%）',10],['trend_allocation','趋势路线额度（%）',100],['quality_allocation','质量路线额度（%）',100],['liquidity_cap','日成交额参与上限（%）',1],['trim_fraction','看空分批防守比例（%）',100]]
const data=computed(()=>state.value?.status==='COMPLETED'?state.value.data:null),running=computed(()=>busy.value||initialLoading.value||state.value?.status==='RUNNING')
const developer=new URLSearchParams(location.search).get('developer')==='1'
const past=computed(()=>(state.value?.conversation||[]).filter(t=>t.run_id!==state.value.run_id))
const label=r=>({REDUCE:'减仓',ADD:'条件加仓',HOLD:'保留',WATCH:'观察'})[r.action]
const fmt=(v,d=2)=>v==null?'—':Number(v).toLocaleString('zh-CN',{maximumFractionDigits:d})
const pct=v=>v==null?'—':fmt(Number(v)*100)+'%'
const stockNames=ids=>ids.map(id=>data.value.changes.find(r=>r.security_id===id)?.name||id).join('、')
const existing=a=>Boolean(props.id)&&original.value.includes(a.entity)
watch(state,s=>{if(s?.status==='COMPLETED')parent.value=s.run_id})
function routeChanged(a){if(a.route_id!=='AUTO')a.horizon=a.route_id==='QUALITY_GROWTH'?'MEDIUM':'SWING'}
function add(){if(assets.value.length<8)assets.value.push(blank())}
async function submit(text){
  if(typeof text==='string')question.value=text
  formError.value=''
  try{
    if(!declared.value)throw Error('请确认已填写账户全部股票持仓。')
    const list=assets.value.map(a=>{if(a.shares===''||a.sellable_shares==='')throw Error('每只股票须明确填写持股数和可卖股数；候选均填0。');return {...a,entity:a.entity.trim(),cost_price:a.cost_price||null,shares:Number(a.shares),sellable_shares:Number(a.sellable_shares),bought_today:Number(a.bought_today||0)}})
    const values=Object.fromEntries(Object.entries(prefs.value).map(([k,v])=>[k,k==='minimum_commission'?v:String(Number(v)/100)]))
    await ctl.submit({assets:list,available_cash:cash.value,reserve_cash:reserve.value,all_holdings_declared:true,input_origin:origin.value,question:question.value,previous_run_id:parent.value,refresh_research:refresh.value,...values})
  }catch(e){formError.value=e.message}
}
function fill(r){assets.value=r.assets.map(a=>({...a,cost_price:a.cost_price||'',shares:String(a.shares),sellable_shares:String(a.sellable_shares),bought_today:String(a.bought_today)}));cash.value=r.available_cash;reserve.value=r.reserve_cash;declared.value=r.all_holdings_declared;origin.value=r.input_origin;original.value=r.assets.map(a=>a.entity);for(const k in prefs.value)prefs.value[k]=k==='minimum_commission'?r[k]:String(Number(r[k])*100);parent.value=state.value.status==='COMPLETED'?state.value.run_id:r.previous_run_id;question.value=''}
let hydrated=false
watch(state,value=>{if(props.id&&!hydrated&&value?.request){hydrated=true;fill(value.request)}})
onMounted(async()=>{
  if(props.id)await ctl.load(props.id)
  else{const pending=pendingTaskDraft(sessionStorage,'portfolio');question.value=sessionStorage.getItem('alpha-portfolio-question')||pending?.question||question.value;if(pending?.entities.length){assets.value=pending.entities.slice(0,8).map(entity=>({...blank(),entity,horizon:pending.horizon}));while(assets.value.length<2)assets.value.push(blank())}sessionStorage.removeItem('alpha-portfolio-question')}
  initialLoading.value=false
})
onUnmounted(ctl.dispose)
</script>
<template>
<div class="page portfolio-advisor" :class="{'has-result':data}">
  <div class="section-heading"><div><h1>账户调仓</h1><p class="muted">先控制整体风险，再判断每笔持仓与调入机会</p></div><div class="bt-actions"><a class="btn" href="#/portfolio-advisor">新账户咨询</a><a href="#/holding-advisor">单股持仓顾问</a><a href="#/">工作台</a></div></div>
  <section class="panel rep-section">
    <details class="input-disclosure" :open="!data"><summary>{{ data?'更新完整账户与调仓偏好':'填写账户持仓与现金' }}</summary>
    <form @submit.prevent="submit()">
      <ResearchDepth :continuing="Boolean(props.id)" />
      <div class="account-cash"><label>当前可用现金（元）<input v-model="cash" required type="number" min="0" max="100000000000" step="0.01"></label><label>保留现金（元）<input v-model="reserve" required type="number" min="0" step="0.01"></label><p class="condition-note">总资产由本轮报价下的全部持仓市值加现金计算。一次 2–8 只沪深 A 股，至少两只已有持仓；名额内可加入最多四只候选，候选股数和可卖数均填 0。</p></div>
      <div class="holdings-scroll" role="region" aria-label="完整持仓资料表，可横向滚动" tabindex="0"><table class="holding-table"><thead><tr><th>股票名称 / 代码</th><th>每股成本（元）</th><th>持股数</th><th>可卖股数</th><th>今日买入</th><th>周期</th><th>原路线</th><th>操作</th></tr></thead><tbody><tr v-for="(a,i) in assets" :key="i"><td><input v-model="a.entity" :aria-label="'股票'+(i+1)" required maxlength="30" :readonly="existing(a)" placeholder="准确名称或六位代码"></td><td><input v-model="a.cost_price" :aria-label="'成本'+(i+1)" type="number" min="0.001" step="any" :required="Number(a.shares)>0"></td><td><input v-model="a.shares" :aria-label="'持股数'+(i+1)" required type="number" min="0" step="1"></td><td><input v-model="a.sellable_shares" :aria-label="'可卖数'+(i+1)" required type="number" min="0" step="1"></td><td><input v-model="a.bought_today" :aria-label="'今日买入'+(i+1)" type="number" min="0" step="1"></td><td><select v-model="a.horizon" :aria-label="'周期'+(i+1)" :disabled="existing(a)"><option value="SWING">波段</option><option value="MEDIUM">中期</option></select></td><td><select v-model="a.route_id" :aria-label="'原路线'+(i+1)" :disabled="existing(a)" @change="routeChanged(a)"><option value="AUTO">按体系匹配</option><option value="TREND_SWING">趋势波段</option><option value="QUALITY_GROWTH">质量成长</option></select></td><td><button type="button" class="btn" :disabled="assets.length<=2||running" :aria-label="'移除股票'+(i+1)" @click="assets.splice(i,1)">移除</button></td></tr></tbody></table></div>
      <div class="account-actions"><button type="button" class="btn" :disabled="assets.length>=8||running" @click="add">添加持仓 / 候选</button><label class="checkbox"><input v-model="declared" type="checkbox" required>已填写本账户全部股票持仓与现金，不含融资或未填持仓</label></div>
      <details><summary>组合风控与费用偏好</summary><div class="preferences"><label v-for="[key,title,max] in fields" :key="key">{{ title }}<input v-model="prefs[key]" type="number" min="0" :max="max" step="0.01"></label><label>佣金假设（%）<input v-model="prefs.commission_rate" type="number" min="0" max="1" step="0.001"></label><label>最低佣金（元）<input v-model="prefs.minimum_commission" type="number" min="0" max="100" step="0.01"></label><label>卖出其他费用（%）<input v-model="prefs.other_sell_cost_rate" type="number" min="0" max="1" step="0.001"></label><label>买入其他费用（%）<input v-model="prefs.other_buy_cost_rate" type="number" min="0" max="1" step="0.001"></label></div><p class="condition-note">这些阈值、路线额度与费用是可修改的执行假设，均未证明盈利。风险预算包含价格至风险参考及假设卖出费用，不能代表最大可能损失。</p></details>
      <div class="question-row"><label>本轮账户问题<textarea v-model="question" required maxlength="2000" rows="2" placeholder="例如：行业是否过度集中？应该先减哪只，哪些有加仓条件？"></textarea></label><div><label v-if="props.id" class="checkbox"><input v-model="refresh" type="checkbox">更新公开资料（新增或移除股票时需要）</label><button class="btn btn-primary" :disabled="running||state?.status==='INTERRUPTED'">{{ running?'正在核查…':props.id?'追问并保存新一轮':'分析整个账户' }}</button></div></div>
      <p class="condition-note">现金、成本、股数与原问题在本地处理；模型接收脱敏后的问题语义、公开股票资料和已审核方法。实际成交后请更新全部持仓与现金。</p>
      <p v-if="formError||error" class="notice error-text" role="alert">{{ formError||error }}</p>
    </form></details>
  </section>
  <section v-if="initialLoading" class="panel rep-section" role="status"><h2>正在读取已保存的组合咨询</h2><p>核对固定知识、公开研究和各轮输入后展示。</p></section>
  <section v-else-if="state?.status==='RUNNING'" class="panel rep-section" role="status"><h2>正在联合分析账户</h2><p>按周期核查每只股票，再计算行业集中度、同窗相关性与先后调仓条件。离开后可从历史库查看。</p></section>
  <section v-else-if="state?.status==='INTERRUPTED'" class="panel rep-section"><h2>本轮资料需要继续核查</h2><p>{{ state.error }}</p><button class="btn" :disabled="busy" @click="ctl.resume">保留全部输入与预算，继续核查</button></section>
  <template v-if="data">
    <p v-if="data.request.input_origin==='SYNTHETIC_ACCEPTANCE'" class="notice">示例账户：使用真实行情，持仓和现金为假设。</p>
    <AdvisorDialogue :dialogue="data.dialogue" />
    <section class="panel rep-section conclusion"><h2>{{ data.headline }}</h2><p class="muted">研究行情截至 {{ data.market_date }} · 保存于 {{ dateTime(state.issued_at) }} · 价格和各项参考按本轮封存数据计算</p><div class="account-metrics"><span>当前总资产<b>{{ fmt(data.before.total_assets) }} 元</b></span><span>股票总仓位<b>{{ pct(data.before.equity_weight) }} → {{ pct(data.after.equity_weight) }}</b></span><span>现金<b>{{ fmt(data.before.cash) }} → {{ fmt(data.after.cash) }} 元</b></span><span>至风险参考的损失<b>{{ fmt(data.before.risk_to_reference) }} → {{ fmt(data.after.risk_to_reference) }} 元</b></span><span>全部条件执行费用<b>{{ fmt(data.after.costs) }} 元</b></span><span>样本年化波动估计<b>{{ pct(data.before.annualized_sample_volatility) }} → {{ pct(data.after.annualized_sample_volatility) }}</b></span></div><p v-for="warning in data.warnings" :key="warning" class="notice">{{ warning }}</p><p class="condition-note">箭头右侧是假设全部条件成交后的投影，未发生交易；样本波动是当前权重套用历史协方差，不是账户实际历史收益。</p></section>
    <section class="panel rep-section"><h2>整体减仓、加仓与调仓安排</h2><ol class="execution"><li v-for="line in data.execution" :key="line">{{ line }}</li></ol><div class="holdings-scroll" role="region" aria-label="逐股调仓建议表，可横向滚动" tabindex="0"><table class="change-table"><thead><tr><th>股票 / 路线</th><th>建议</th><th>原股数 → 条件股数</th><th>建议卖出</th><th>条件买入</th><th>仓位变化</th><th>理由与等待条件</th></tr></thead><tbody><tr v-for="r in data.changes" :key="r.security_id"><td><strong>{{ r.name }}</strong><small>{{ r.security_id }} · {{ r.route_title }}</small><small>报价 {{ fmt(r.quote.price) }} · {{ dateTime(r.quote.quoted_at) }}</small></td><td><span class="tag">{{ label(r) }}</span></td><td>{{ fmt(r.current_shares,0) }} → {{ fmt(r.target_shares,0) }}</td><td>{{ fmt(r.sell_shares,0) }} 股<small>可卖 {{ fmt(r.sellable_shares,0) }}；本轮上限 {{ fmt(r.sell_limit,0) }}</small></td><td>{{ fmt(r.buy_shares,0) }} 股</td><td>{{ pct(r.before_weight) }} → {{ pct(r.after_weight) }}</td><td><p v-for="why in r.reduction_reasons" :key="why">{{ why }}</p><p>{{ r.add_reason }}</p><details><summary>研究理由、反证和退出条件</summary><p><strong>{{ r.opinion.summary }}</strong></p><p v-for="c in r.opinion.claims" :key="c.claim_id">{{ c.text }}</p><p v-for="c in r.opinion.opposing" :key="c.claim_id">反证：{{ c.text }}</p><p v-for="v in r.invalidation" :key="v">{{ v }}</p><p>风险参考 {{ fmt(r.risk_reference) }} 元；费用试算：卖 {{ fmt(r.sell_cost) }} 元，买 {{ fmt(r.buy_cost) }} 元。</p><a :href="'#/investment-research/'+r.research_run_id">查看该组完整研究</a></details></td></tr></tbody></table></div></section>
    <section class="account-plots"><article class="panel rep-section"><h2>持仓与现金</h2><PrototypeChart :block="exposureChart(data)" :height="Math.max(260,data.changes.length*35+75)" /></article><article class="panel rep-section"><h2>行业集中度</h2><PrototypeChart :block="exposureChart(data,'industries')" :height="Math.max(260,data.before.industries.length*40+75)" /><p>上限 {{ pct(data.request.industry_cap) }}，以账户总资产为分母。</p></article></section>
    <section class="account-plots"><article class="panel rep-section"><h2>股票之间的相关性</h2><PrototypeChart :block="correlationChart(data)" :height="350" /><p class="condition-note">{{ data.correlation.sample_count }} 个共同交易日日收益；{{ data.correlation.sessions[0]||'窗口不足' }}—{{ data.correlation.sessions.at(-1)||'—' }}。空格为不可计算，不是零相关。</p></article><article class="panel rep-section"><h2>需要一起控制的风险</h2><div v-for="(g,i) in data.correlated_groups" :key="i" class="cluster"><strong>{{ stockNames(g.members) }}</strong><p>相关持仓群 {{ pct(g.before_weight) }} → {{ pct(g.after_weight) }} · 上限 {{ pct(data.request.correlated_cap) }}</p></div><p v-if="!data.correlated_groups.length">{{ data.correlation.status==='COMPUTED'?'当前共同窗口未形成超过阈值的正相关群。':'共同窗口不完整，未推断相关群。' }}</p><details v-if="data.initial_breaches.length"><summary>当前超出的约束</summary><p v-for="b in data.initial_breaches" :key="b.label">{{ b.label }}：超出约 {{ fmt(b.excess) }} 元</p></details><div v-if="data.unresolved.length" class="notice"><strong>以下约束尚未解除，暂停新增买入</strong><p v-for="b in data.unresolved" :key="b.label">{{ b.label }}仍超出 {{ fmt(b.excess) }} 元。可卖数量或流动性限制下，需要等待并更新账户。</p></div><p class="condition-note">阈值 {{ pct(data.request.correlation_threshold) }}；相关群包含传递连接，群内不是每对都高相关。负相关也不保证未来对冲。</p></article></section>

    <section class="panel rep-section"><h2>继续问这个账户</h2><div class="ask-chips"><button v-for="text in ['哪个行业最集中，应该先减哪只？','当前还有哪些加仓或调入条件？','哪些卖出受到可卖数量和流动性约束？','这次调仓依据哪些投资方法？']" :key="text" class="chip" :disabled="running" @click="submit(text)">{{ text }}</button></div><p class="condition-note">可修改上方现金、数量和约束后发送；新增或移除股票需勾选更新资料。每轮另存，不改写旧建议。</p><details v-if="past.length"><summary>查看此前 {{ past.length }} 轮账户对话</summary><p v-for="t in past" :key="t.run_id">{{ t.question }} → {{ t.data?.headline||t.status }} <a :href="'#/portfolio-advisor/'+t.run_id">回看该轮</a></p></details><details><summary>统一知识体系的方法依据</summary><div v-for="m in data.knowledge" :key="m.rule_id"><p><strong>{{ m.title }}</strong>：{{ m.system_rule }}</p></div></details><details class="result-notes"><summary>计算口径与风险说明</summary><p v-for="note in data.caveats" :key="note" class="condition-note">{{ note }}</p></details><a class="btn" :href="'/api/quant/portfolio-advisor/turns/'+state.run_id+'/export'">导出本地账户咨询记录</a></section>
    <details v-if="developer&&state.understanding" class="panel rep-section"><summary>开发者：语义理解与脱敏投影</summary><pre>{{ state.understanding }}</pre></details>
    <details v-if="developer" class="panel rep-section"><summary>开发者：组合计算与知识绑定</summary><pre>{{ {run_id:state.run_id,engine:data.engine_version,research:data.research_bindings,knowledge:data.knowledge,privacy:data.privacy,elapsed_seconds:state.elapsed_seconds,correlation:data.correlation,quotes:data.quotes} }}</pre></details>
  </template>
</div>
</template>
<style scoped>
.portfolio-advisor label{display:grid;gap:6px;font-size:12px;color:var(--text-2)}.portfolio-advisor input,.portfolio-advisor select,.portfolio-advisor textarea{width:100%;min-width:0;padding:8px;border:1px solid var(--border);border-radius:4px;background:var(--bg-raised);color:var(--text-1);font:inherit}.account-cash{display:grid;grid-template-columns:1fr 1fr 2fr;gap:16px;align-items:end;margin-bottom:16px}.holdings-scroll{max-width:100%;overflow-x:auto}.holding-table,.change-table{width:100%;border-collapse:collapse;font-size:12px;min-width:950px}.holding-table th,.holding-table td,.change-table th,.change-table td{text-align:left;padding:8px;border-bottom:1px solid var(--border);vertical-align:top}.holding-table input{min-width:85px}.holding-table td:first-child{min-width:150px}.holding-table select{min-width:85px}.account-actions{display:flex;gap:18px;align-items:center;margin:12px 0}.portfolio-advisor .checkbox{display:flex;align-items:center;gap:8px}.checkbox input{width:auto}.preferences{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:14px 0}.question-row{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:end;gap:16px;margin-top:16px}.question-row .btn{margin-top:12px}.account-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;background:var(--bg-raised);padding:14px;margin:16px 0;font-size:12px;color:var(--text-2)}.account-metrics b{display:block;font-size:18px;color:var(--text-1);margin-top:6px}.conclusion{border-left:3px solid var(--accent)}.conclusion h2{color:var(--accent)}.account-plots{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.account-plots .rep-section{margin-top:0}.cluster{border-bottom:1px solid var(--border);padding:10px 0}.change-table small{display:block;color:var(--text-2);font-size:11px;margin-top:6px}.change-table td:last-child{min-width:240px}.change-table p{margin:0 0 6px;line-height:1.6}.execution{font-size:13px;line-height:1.8;padding-left:20px}.portfolio-advisor summary{cursor:pointer;color:var(--text-2);font-size:13px;margin:10px 0}.portfolio-advisor pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:600px;overflow:auto;font-size:11px}.portfolio-advisor :is(input,select,textarea,button,summary,a,[tabindex]):focus-visible{outline:2px solid var(--accent);outline-offset:2px}@media(max-width:850px){.account-cash,.account-plots,.question-row{grid-template-columns:1fr}.account-metrics,.preferences{grid-template-columns:repeat(2,minmax(0,1fr))}.account-actions{align-items:flex-start;flex-direction:column}.question-row .btn{width:100%}.portfolio-advisor .section-heading{flex-wrap:wrap;gap:12px}}
</style>
